const listFinanceCategories = `-- name: ListFinanceCategories :many


SELECT c.id, c.uuid, c.kind, c.code, c.name, c.is_system, c.status, c.sort_order, c.created_at, c.updated_at,
    (SELECT COUNT(*) FROM finance_entries e
      WHERE e.organization_id = c.organization_id AND e.category_id = c.id AND e.entry_type = 'entry')::bigint AS entry_count
FROM finance_categories c
WHERE c.organization_id = $1
  AND ($2::text[] IS NULL OR c.kind = ANY($2::text[]))
  AND ($3::text[] IS NULL OR c.status = ANY($3::text[]))
  AND ($4::text IS NULL OR c.name ILIKE '%' || $4 || '%')
ORDER BY
  CASE WHEN $5::text = 'name' AND NOT $6::boolean THEN lower(c.name) END ASC,
  CASE WHEN $5::text = 'name' AND $6::boolean THEN lower(c.name) END DESC,
  CASE WHEN $5::text = 'kind' AND NOT $6::boolean THEN c.kind END ASC,
  CASE WHEN $5::text = 'kind' AND $6::boolean THEN c.kind END DESC,
  CASE WHEN $5::text = 'status' AND NOT $6::boolean THEN c.status END ASC,
  CASE WHEN $5::text = 'status' AND $6::boolean THEN c.status END DESC,
  CASE WHEN $5::text = 'sort_order' AND NOT $6::boolean THEN c.sort_order END ASC,
  CASE WHEN $5::text = 'sort_order' AND $6::boolean THEN c.sort_order END DESC,
  CASE WHEN $5::text = 'created_at' AND NOT $6::boolean THEN c.created_at END ASC,
  CASE WHEN $5::text = 'created_at' AND $6::boolean THEN c.created_at END DESC,
  c.kind DESC, c.sort_order, lower(c.name), c.id
LIMIT $8 OFFSET $7
`

